  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 Understanding Credit and Credit Cards$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "Credit is the ability to borrow money or buy now with a promise to pay later. Scripture is plain about the weight of borrowing. Proverbs 22:7 says, The rich ruleth over the poor, and the borrower is servant to the lender. Romans 13:8 says, Owe no man any thing, but to love one another: for he that loveth another hath fulfilled the law. Debt is not always a sin, but it always has a cost and a risk, and the goal is to owe as little as possible and pay it back on time.\n\nA credit card lets you borrow up to a limit from a lender each time you swipe. It is not free money. At the end of the billing cycle you receive a statement with the balance, the minimum payment and a due date. If you pay the full statement balance by the due date, you usually pay no interest, because of a grace period. If you carry a balance, interest is charged at the card's annual percentage rate, or APR, which is often high. A balance of 1,000 dollars at an 18 percent APR costs about 15 dollars in interest in one month.\n\nThe minimum payment trap catches many people. Paying only the minimum keeps the account current but stretches payments over years, and the total interest can approach or exceed the original purchase. Late payments bring fees and may raise your rate and hurt your credit. Cash advances usually bring a fee and a higher rate with no grace period.\n\nCredit cards have benefits when used well. They offer fraud protection, a record of purchases and sometimes rewards. They can also build a credit history. The wise rule is to treat a credit card like a debit card: only charge what you can pay in full from money you already have.\n\nFederal law limits who can get a card. A person under 21 generally needs independent income or a cosigner. Read the terms and look for annual fees, the APR and penalty rates.\n\nYour task: (1) Explain how a grace period works. (2) Calculate one month of interest on a 500 dollar balance at 24 percent APR. (3) Describe the minimum payment trap.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Proverbs 22:7 says, The rich ruleth over the poor, and the borrower is servant to the lender. And Romans 13:8 says, Owe no man any thing, but to love one another. Debt always has a cost and a risk.\n\nNow watch this. A credit card lets you borrow up to a limit. It is not free money. Each month you get a statement with a balance, a minimum payment and a due date. Pay the full balance by the due date and you usually pay no interest, because of the grace period. Carry a balance and interest is charged at the APR. A thousand dollars at 18 percent costs about 15 dollars in one month.\n\nThe minimum payment trap keeps the account current but stretches payments over years and can cost as much in interest as the purchase. Late payments bring fees and hurt your credit. Cash advances cost more.\n\nUse a credit card like a debit card. Only charge what you can pay in full. Look for fees, the APR and penalty rates. Those under 21 generally need income or a cosigner.\n\nYour task is to explain the grace period, calculate interest and describe the minimum payment trap. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 Understanding Credit and Credit Cards$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Credit Reports and Credit Scores$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "A credit report is a record of your borrowing history, kept by credit bureaus. The three national bureaus are Equifax, Experian and TransUnion. A report lists your accounts, balances, payment history, inquiries and public records. A credit score is a number that summarizes the risk of lending to you. The best known scores, such as FICO, generally range from 300 to 850, and higher is better.\n\nLenders, landlords, insurers and some employers may check credit. A good score can help you qualify for loans and lower rates. A poor score can mean higher interest or denial, and a few dollars of difference in rate can add up to thousands over years. Proverbs 22:1 says, A good name is rather to be chosen than great riches. A reputation for paying what you owe is valuable.\n\nFive factors shape a typical FICO score. Payment history carries the most weight, about 35 percent. Amounts owed, including how much of your limit you use, is about 30 percent. Length of credit history is about 15 percent. New credit and recent inquiries are about 10 percent. The mix of credit types is about 10 percent. Keep your credit use below about 30 percent of your limit, and lower is better. Pay every bill on time. Avoid opening many accounts quickly.\n\nYou can get free credit reports from each bureau at AnnualCreditReport.com, the only site authorized by federal law for free reports. Review them for errors, such as accounts that are not yours, and dispute mistakes in writing with the bureau. Checking your own report does not lower your score. A credit score is separate from a report and may be offered by banks or apps.\n\nYoung people can start building credit by becoming an authorized user on a parent's account if the parent has a good record, using a secured card, which is backed by a deposit, or taking a small credit builder loan, all once they are legally able to do so. Be careful of companies that promise to erase bad credit for a fee.\n\nYour task: (1) Name the three credit bureaus. (2) List the five factors of a credit score. (3) Explain how to get free credit reports.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Proverbs 22:1 says, A good name is rather to be chosen than great riches. A reputation for paying what you owe is valuable.\n\nNow watch this. A credit report is your borrowing history, kept by Equifax, Experian and TransUnion. A credit score summarizes lending risk. FICO scores generally run from 300 to 850.\n\nLenders, landlords, insurers and some employers may check it. A better score can mean lower rates.\n\nFive factors. Payment history, about 35 percent. Amounts owed, about 30 percent. Length of history, about 15 percent. New credit, about 10 percent. Credit mix, about 10 percent. Pay on time, keep use below about 30 percent of your limit and avoid opening many accounts quickly.\n\nGet free reports at AnnualCreditReport.com. Review them for errors and dispute mistakes in writing. Checking your own report does not lower your score.\n\nTo build credit, ask about being an authorized user on a parent's account, a secured card or a credit builder loan, once you are legally able. Beware of companies that promise to erase bad credit for a fee.\n\nYour task is to name the bureaus, list the factors and explain free reports. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Credit Reports and Credit Scores$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Loans: Cars, Education and Homes$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "A loan is money borrowed that must be repaid with interest. Key terms are principal, which is the amount borrowed, interest, which is the cost, the term, which is the length of the loan, and the APR, which is the yearly cost including some fees. A longer term usually lowers the monthly payment but raises the total interest paid. Always compare the total cost, not just the payment.\n\nLoans can be secured or unsecured. A secured loan is backed by collateral, such as a car or home, which the lender can take if you do not pay. An unsecured loan has no collateral, such as most credit cards and personal loans, and often carries a higher rate.\n\nAuto loans fund cars, which lose value quickly. A larger down payment, a shorter term and a used car that fits the budget reduce risk. Owing more than a car is worth is a trap. Mortgages fund homes, usually for fifteen or thirty years, and need a down payment, closing costs, insurance and property taxes. Home buying requires careful planning, and Proverbs 24:27 teaches, Prepare thy work without, and make it fit for thyself in the field; and afterwards build thine house.\n\nEducation loans deserve special care. Federal student loans usually have fixed rates and protections, and you apply through the Free Application for Federal Student Aid, or FAFSA. Private loans usually have fewer protections. Before borrowing, look for scholarships, grants, which do not need to be repaid, work and lower cost options. Borrow only what you need, and compare the expected pay for your field with the amount of debt.\n\nCosigning means promising to pay if someone else does not. Proverbs 22:26 and 27 warn, Be not thou one of them that strike hands, or of them that are sureties for debts. If thou hast nothing to pay, why should he take away thy bed from under thee? Think carefully before cosigning, since you become fully responsible.\n\nBeware of payday loans, title loans and rent to own plans. They can have extremely high effective rates and trap borrowers.\n\nYour task: (1) Define principal, interest, term and collateral. (2) Compare a secured and an unsecured loan. (3) Explain what Proverbs 22:26 and 27 warn about.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Proverbs 22:26 and 27 say, Be not thou one of them that strike hands, or of them that are sureties for debts. If thou hast nothing to pay, why should he take away thy bed from under thee? Cosigning makes you fully responsible.\n\nNow watch this. A loan has a principal, interest, a term and an APR. A longer term lowers the payment but raises the total interest. Compare total cost.\n\nA secured loan has collateral the lender can take, like a car or home. An unsecured loan has none and often costs more.\n\nCars lose value fast. Use a bigger down payment, a shorter term and a car that fits the budget. Mortgages need a down payment, closing costs, insurance and taxes. Proverbs 24:27 says, Prepare thy work without, and make it fit for thyself in the field; and afterwards build thine house.\n\nFor college, use the FAFSA. Look for scholarships and grants first, since grants do not need to be repaid. Borrow only what you need and compare expected pay with the debt.\n\nBeware of payday loans, title loans and rent to own plans.\n\nYour task is to define loan terms, compare secured and unsecured loans and explain the warning about sureties. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Loans: Cars, Education and Homes$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Escaping and Avoiding the Debt Trap$j$, $j${"readings": [{"title": "Psalm 37 (King James Version)", "url": "/portal/bible/Psalms/37"}], "body": "Many people find themselves in debt, and there is a way out. Psalm 37:21 says, The wicked borroweth, and payeth not again: but the righteous sheweth mercy, and giveth. Faithful stewards pay what they owe. Proverbs 15:22 adds, Without counsel purposes are disappointed: but in the multitude of counsellors they are established. Seek help early and do not hide the problem.\n\nThe first step is to face the numbers. List every debt, with its balance, interest rate and minimum payment. Stop adding new debt. Build a small emergency fund so a surprise does not send you back to the credit card. Then choose a payoff plan. In the debt snowball method, you pay the minimum on all debts and put every extra dollar on the smallest balance, then roll that payment to the next one. It gives quick wins and motivation. In the debt avalanche method, you put extra money on the debt with the highest interest rate first. It saves the most money. Either works if you stay consistent.\n\nIncrease the gap between income and spending by trimming wants, selling items you do not need and earning extra income. Ask lenders about lower rates or hardship plans. Nonprofit credit counseling agencies, such as members of the National Foundation for Credit Counseling, can help make a plan. Be careful of debt settlement companies that charge high fees and promise to erase debt.\n\nBankruptcy is a legal process that can discharge some debts, but it harms credit for years and does not erase every debt. It is a last resort and should be considered with qualified legal advice.\n\nAvoid the trap in the first place. Buy now, pay later plans can encourage spending and cause missed payments. Do not borrow for wants that lose value, and do not use debt to keep up with others. Save for purchases and pay cash when possible. Keep a margin in the budget. Remember that Proverbs 22:3 teaches the prudent to foresee evil and avoid it.\n\nYour task: (1) Compare the debt snowball and the debt avalanche. (2) List four steps to get out of debt. (3) Explain where to find trustworthy help.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Psalm 37:21 says, The wicked borroweth, and payeth not again: but the righteous sheweth mercy, and giveth. And Proverbs 15:22 says, Without counsel purposes are disappointed. Seek help early.\n\nNow watch this. Face the numbers. List every debt with the balance, rate and minimum payment. Stop adding new debt. Build a small emergency fund.\n\nThe debt snowball pays the smallest balance first for quick wins. The debt avalanche pays the highest interest rate first and saves the most money. Either works if you stay consistent.\n\nTrim wants, sell what you do not need and earn extra income. Ask lenders about lower rates or hardship plans. Nonprofit credit counseling, like members of the National Foundation for Credit Counseling, can help. Beware of debt settlement companies that charge high fees.\n\nBankruptcy is a last resort and harms credit for years. Get qualified legal advice.\n\nAvoid the trap. Be careful with buy now pay later plans. Do not borrow for wants that lose value. Save and pay cash when possible. Keep a margin in your budget.\n\nYour task is to compare snowball and avalanche, list steps out of debt and name trustworthy help. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Escaping and Avoiding the Debt Trap$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Credit and Debt$j$, $j${"prompt": "Write a report of at least 250 words, with calculations, on credit and debt. Use complete sentences and label each part. Proverbs 22:7 says, The rich ruleth over the poor, and the borrower is servant to the lender.\n\nPart 1: Explain how a credit card works, including the grace period, APR and the minimum payment trap. Calculate one month of interest on a 600 dollar balance at a 24 percent APR.\nPart 2: Name the three credit bureaus, the five factors in a credit score, and three habits that help a score. Explain how to get free credit reports.\nPart 3: Define principal, interest, term, secured loan, unsecured loan and collateral. Explain why a longer loan term can cost more overall. Explain Proverbs 22:26 and 27 about cosigning.\nPart 4: Compare the debt snowball and the debt avalanche. Write a four step plan for a person with three debts.\nPart 5: Describe three dangers such as payday loans or buy now pay later plans, and explain how Romans 13:8 and Psalm 37:21 guide a believer about debt.", "rubric": "100 points. Part 1: 25 points. Part 2: 20 points. Part 3: 20 points. Part 4: 15 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Credit and Debt$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Owe No Man Any Thing$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes how you or someone you know has seen debt help or hurt a family, with no names, (2) explains in your own words why a good credit record is valuable, (3) explains what you would do to avoid debt or pay it off, and (4) connects your answer to Proverbs 22:7, Romans 13:8, Psalm 37:21 or Proverbs 22:1. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Is all debt wrong? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Owe No Man Any Thing$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Understanding Credit and Credit Cards$j$, $j${"questions": [{"q": "According to Proverbs 22:7, the borrower is:", "options": ["Master of the lender", "Free of cost", "Servant to the lender", "Always blessed"]}, {"q": "Paying the full statement balance by the due date usually means you pay:", "options": ["A cash advance fee", "A tax", "No interest", "Double interest"]}, {"q": "APR stands for:", "options": ["Account payment review", "Annual purchase refund", "Average payment record", "Annual percentage rate"]}, {"q": "Paying only the minimum on a credit card balance usually:", "options": ["Raises your savings", "Lowers the APR", "Costs much more in interest over time", "Eliminates debt quickly"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Understanding Credit and Credit Cards$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,3,2}'::int[], array[$j$Debt creates obligation.$j$,$j$The grace period avoids interest.$j$,$j$APR is the yearly cost of borrowing.$j$,$j$Minimums stretch the debt out.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Understanding Credit and Credit Cards$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Credit Reports and Credit Scores$j$, $j${"questions": [{"q": "Which factor has the greatest weight in a typical FICO score?", "options": ["Payment history", "Your age", "Length of your name", "Your address"]}, {"q": "Which is one of the three national credit bureaus?", "options": ["Venmo", "Zillow", "Kroger", "Experian"]}, {"q": "The authorized site for free credit reports is:", "options": ["Any ad that promises a free score", "A social media page", "A game site", "AnnualCreditReport.com"]}, {"q": "A FICO score generally ranges from:", "options": ["1 to 100", "1,000 to 5,000", "300 to 850", "0 to 10"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Credit Reports and Credit Scores$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,3,2}'::int[], array[$j$Paying on time matters most.$j$,$j$Equifax, Experian and TransUnion are the three.$j$,$j$It is the site authorized by federal law.$j$,$j$That is the typical FICO range.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Credit Reports and Credit Scores$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Loans: Cars, Education and Homes$j$, $j${"questions": [{"q": "The amount of money borrowed in a loan is the:", "options": ["Collateral", "Premium", "Dividend", "Principal"]}, {"q": "Property pledged to secure a loan is called:", "options": ["A premium", "Collateral", "A dividend", "A grant"]}, {"q": "Money for college that does not need to be repaid is a:", "options": ["Payday loan", "Credit card", "Grant", "Private loan"]}, {"q": "Cosigning a loan means you:", "options": ["Only give advice", "Pay nothing ever", "Promise to pay if the borrower does not", "Have no responsibility"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Loans: Cars, Education and Homes$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,2,2}'::int[], array[$j$Principal is the amount borrowed.$j$,$j$The lender can take collateral if you default.$j$,$j$Grants and scholarships are gift aid.$j$,$j$A cosigner is fully responsible.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Loans: Cars, Education and Homes$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Escaping and Avoiding the Debt Trap$j$, $j${"questions": [{"q": "The debt method that pays the highest interest rate first is the:", "options": ["Snowball", "Minimum only", "Rollover", "Avalanche"]}, {"q": "The debt method that pays the smallest balance first is the:", "options": ["Avalanche", "Snowball", "Balloon", "Reverse"]}, {"q": "A trustworthy source of help with debt is a:", "options": ["Company promising to erase debt for a big fee", "Nonprofit credit counseling agency", "Payday lender", "Stranger online"]}, {"q": "Bankruptcy should generally be considered:", "options": ["A way to build credit quickly", "A routine budget tool", "The first step", "A last resort with legal advice"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Escaping and Avoiding the Debt Trap$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,1,3}'::int[], array[$j$The avalanche saves the most interest.$j$,$j$The snowball builds quick wins.$j$,$j$Nonprofit counselors can help build a plan.$j$,$j$It has long lasting costs.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Escaping and Avoiding the Debt Trap$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Credit and Debt$j$, $j${"questions": [{"q": "Interest rate on a credit card is expressed as the:", "options": ["FICA", "APR", "FDIC", "CD"]}, {"q": "The minimum payment trap means:", "options": ["The minimum clears the debt quickly", "Paying only the minimum keeps you in debt for years", "Your score always rises", "Interest stops"]}, {"q": "Credit scores are summaries of:", "options": ["Bank hours", "Credit reports", "Pay stubs", "Tax forms"]}, {"q": "The most important factor in a credit score is:", "options": ["The size of your car", "Having many new cards", "Paying on time", "Your favorite color"]}, {"q": "A loan backed by collateral is:", "options": ["A grant", "A gift", "Secured", "Unsecured"]}, {"q": "Federal student aid is applied for with the:", "options": ["W4", "ACH", "FAFSA", "FICO"]}, {"q": "Which debt payoff method targets the highest interest rate first?", "options": ["Snowball", "Avalanche", "Rollover", "Cash advance"]}, {"q": "Romans 13:8 says to:", "options": ["Avoid paying", "Cosign for everyone", "Owe no man any thing, but to love one another", "Borrow freely"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Credit and Debt$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,2,2,2,1,2}'::int[], array[$j$APR is the annual percentage rate.$j$,$j$Interest keeps building.$j$,$j$Scores come from report data.$j$,$j$Payment history has the biggest weight.$j$,$j$Secured loans have collateral.$j$,$j$The FAFSA is the federal aid application.$j$,$j$The avalanche saves the most money.$j$,$j$Scripture urges us to avoid owing.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Credit and Debt$j$ on conflict (item_id) do nothing;
